47		                                                   List<GatewaySecurityPolicyCustomizer> customizers) {
48			RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props, customizers);
49			resolver.afterPropertiesSet();
50			return resolver.resolve(path, method);
