37	@DisplayName("JwtAuthenticationGatewayFilter tests")
38	class JwtAuthenticationGatewayFilterTest {
39	
40		private static final String SECRET = "my-test-secret-key-minimum-256-bits-long!!";
41		private static final String ISSUER = "maritime-platform";
42	
43		private GatewaySecurityProperties properties;
44		private SecretKey signingKey;
