46		@BeforeEach
47		void setUp() {
48			properties = new GatewaySecurityProperties();
49			properties.getJwt().setEnabled(true);
50			properties.getJwt().setSecret(SECRET);
51			properties.getJwt().setIssuer(ISSUER);
52			signingKey = Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8));
53		}
