62			Instant now = Instant.now();
63			return Jwts.builder()
64					.issuer(ISSUER)
65					.claim("userId", "user-123")
66					.claim("userName", "TestUser")
67					.claim("sessionId", "session-abc")
68					.issuedAt(Date.from(now))
69					.expiration(Date.from(now.plus(1, ChronoUnit.HOURS)))
70					.signWith(signingKey)
71					.compact();
72		}
