103			void orderPositionInCorrectRange() {
104				assertThat(GatewayFilterOrder.JWT_AUTHENTICATION)
105						.isGreaterThan(GatewayFilterOrder.SECURITY_POLICY);
106				assertThat(GatewayFilterOrder.JWT_AUTHENTICATION)
107						.isLessThan(GatewayFilterOrder.CONTEXT_HEADER_INJECTION);
