			StepVerifier.create(filter().filter(exchange, passThroughChain()))
					.verifyComplete();

			String body = exchange.getResponse().getBodyAsString().block();
			assertThat(body).contains(GatewayAuthErrorCode.TIMESTAMP_EXPIRED);
		}

		@Test
